namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

public class RecipeSubmission
{
    public required string Title { get; set; }
    public required string Category { get; set; }
    public required string Description { get; set; }
    public required string Ingredients { get; set; }
    public required string Steps { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious traditional Italian pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone.",
                    "Stretch dough into a 12-inch circle.",
                    "Spread crushed tomatoes over the dough.",
                    "Tear mozzarella into pieces and distribute evenly.",
                    "Bake for 10–12 minutes until crust is golden.",
                    "Top with fresh basil and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 4, 5]
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, pecorino cheese, guanciale, and black pepper.",
                Ingredients = ["Spaghetti", "Guanciale or pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp guanciale in a pan over medium heat.",
                    "Whisk eggs with grated pecorino and pepper.",
                    "Toss hot pasta with guanciale, then remove from heat.",
                    "Quickly stir in egg mixture, tossing to create a creamy sauce.",
                    "Serve immediately with extra pecorino and pepper."
                ],
                Ratings = [5, 5, 4]
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until charred.",
                    "Sauté onion, garlic, and ginger until soft.",
                    "Add tomato sauce and spices, simmer 15 minutes.",
                    "Stir in cream and add the cooked chicken.",
                    "Simmer 10 minutes and serve over basmati rice."
                ],
                Ratings = [5, 4, 5, 5]
            },
            new()
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A vibrant stir-fried noodle dish with crispy tofu and tangy tamarind sauce.",
                Ingredients = ["Rice noodles", "Firm tofu", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Eggs", "Garlic"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes.",
                    "Press and cube tofu, then pan-fry until golden.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry garlic, then add eggs and scramble.",
                    "Add noodles and sauce, toss until coated.",
                    "Top with tofu, bean sprouts, peanuts, and lime wedges."
                ],
                Ratings = [4, 4, 5]
            },
            new()
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm corn tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Corn tortillas", "Onion", "Cilantro", "Lime", "Chili powder", "Cumin", "Salsa", "Avocado", "Sour cream"],
                Steps = [
                    "Brown ground beef with diced onion.",
                    "Season with chili powder, cumin, salt, and pepper.",
                    "Warm tortillas on a dry skillet.",
                    "Fill tortillas with seasoned beef.",
                    "Top with salsa, avocado, cilantro, and a squeeze of lime.",
                    "Serve with sour cream on the side."
                ],
                Ratings = [4, 5, 4, 4]
            },
            new()
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour ramekins.",
                    "Melt chocolate and butter together.",
                    "Whisk eggs with sugar until thick.",
                    "Fold chocolate mixture into eggs, then add flour.",
                    "Pour into ramekins and bake 12–14 minutes.",
                    "Invert onto plates and serve immediately."
                ],
                Ratings = [5, 5, 5, 4, 5]
            },
            new()
            {
                Id = 7, Title = "Greek Salad", Category = "Mediterranean",
                Description = "A fresh and vibrant salad with tomatoes, cucumbers, olives, and feta cheese.",
                Ingredients = ["Tomatoes", "Cucumber", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Red wine vinegar", "Oregano"],
                Steps = [
                    "Chop tomatoes and cucumber into large chunks.",
                    "Slice red onion thinly.",
                    "Combine vegetables with olives in a bowl.",
                    "Whisk olive oil, vinegar, and oregano for dressing.",
                    "Pour dressing over salad and toss gently.",
                    "Top with a generous block of feta cheese."
                ],
                Ratings = [4, 4, 3, 5]
            },
            new()
            {
                Id = 8, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh, creamy avocado dip with lime, cilantro, and a kick of jalapeño.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt", "Garlic"],
                Steps = [
                    "Halve and pit the avocados, scoop into a bowl.",
                    "Mash to desired consistency.",
                    "Stir in lime juice, diced onion, and minced garlic.",
                    "Add chopped cilantro, tomato, and jalapeño.",
                    "Season with salt and serve with tortilla chips."
                ],
                Ratings = [5, 4, 5]
            },
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        });
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService Recipes

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayStars ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _displayStars = star"
              @onmouseout="() => _displayStars = _selectedStars"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _selectedStars;
    private int _displayStars;
    private bool _submitted;

    private void Rate(int stars)
    {
        if (_submitted) return;
        _selectedStars = stars;
        _displayStars = stars;
        Recipes.AddRating(RecipeId, stars);
        _submitted = true;
    }
}

