.star-rating {
    display: inline-flex;
    align-items: center;
    gap: 0.15rem;
}

.star {
    font-size: 1.75rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover {
    transform: scale(1.2);
}

.star.filled {
    color: #f5a623;
}

.rating-thanks {
    margin-left: 0.75rem;
    color: #28a745;
    font-weight: 500;
    font-size: 0.9rem;
}

@page "/"
@using RecipeHub.Services
@inject RecipeService Recipes

<PageTitle>RecipeHub — Home</PageTitle>

<div class="hero">
    <h1>🍳 Welcome to RecipeHub</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in Recipes.GetCategories())
    {
        <a href="category/@category" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <h3>@category</h3>
            <p>@Recipes.GetByCategory(category).Count recipe(s)</p>
        </a>
    }
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        "Mediterranean" => "🥗",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in _recipes)
        {
            <a href="recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <div class="recipe-meta">
