toolArgs.file_text:
@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in _recipes)
        {
            <a href="recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <div class="recipe-meta">
                    <span class="stars-display">
                        @for (int i = 1; i <= 5; i++)
                        {
                            <span class="@(i <= Math.Round(recipe.AverageRating) ? "star-filled" : "star-empty")">★</span>
                        }
                    </span>
                    <span>@recipe.AverageRating / 5</span>
                    <span class="dot">·</span>
                    <span>@recipe.Ratings.Count rating(s)</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService Recipes

@if (_recipe is null)
{
    <PageTitle>Not Found — RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <p><a href="/">Back to home</a></p>
}
else
{
    <PageTitle>@_recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <article class="recipe-detail">
        <h1>@_recipe.Title</h1>
        <p class="recipe-description">@_recipe.Description</p>

        <div class="recipe-stats">
            <span class="stars-display">
                @for (int i = 1; i <= 5; i++)
                {
                    <span class="@(i <= Math.Round(_recipe.AverageRating) ? "star-filled" : "star-empty")">★</span>
                }
            </span>
            <span>@_recipe.AverageRating / 5 (@_recipe.Ratings.Count ratings)</span>
        </div>

        <section>
            <h2>🧾 Ingredients</h2>
            <ul class="ingredient-list">
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section>
            <h2>👨‍🍳 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in _recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>

        <section class="rating-section">
            <h2>⭐ Rate This Recipe</h2>
            <StarRating RecipeId="_recipe.Id" />
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added.
        <a href="category/@_model.Category">View it in @_model.Category</a>.
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">— Select a category —</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="Mediterranean">Mediterranean</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="ingredients">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_model.Ingredients"
                           placeholder="One ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps"
                           placeholder="One step per line&#10;e.g.&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmissionForm _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        Recipes.AddRecipe(new RecipeSubmission
        {
            Title = _model.Title,
            Category = _model.Category,
            Description = string.Empty,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        });
        _submitted = true;
    }

    private class RecipeSubmissionForm
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

