    color: inherit;
}

.category-icon {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
}

.category-card h3 {
    margin: 0.25rem 0;
    font-size: 1.1rem;
}

.category-card p {
    margin: 0;
    color: #777;
    font-size: 0.9rem;
}

.recipe-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.recipe-card {
    display: block;
    padding: 1.25rem;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.recipe-card:hover {
    box-shadow: 0 2px 12px rgba(0,0,0,0.08);
    text-decoration: none;
    color: inherit;
}

.recipe-card h3 {
    margin: 0 0 0.5rem;
    font-size: 1.2rem;
}

.recipe-card p {
    margin: 0 0 0.5rem;
    color: #555;
}

.recipe-meta {
    font-size: 0.85rem;
    color: #888;
    display: flex;
    align-items: center;
    gap: 0.35rem;
}

.dot {
    margin: 0 0.15rem;
}

.star-filled {
    color: #f5a623;
}

.star-empty {
    color: #ddd;
}

.recipe-detail {
    max-width: 720px;
}

.recipe-description {
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 1rem;
}

.recipe-stats {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
    color: #666;
}

.ingredient-list li, .steps-list li {
    margin-bottom: 0.35rem;
}

.rating-section {
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.darker-border-checkbox.form-check-input {
    border-color: #929292;
}

